class Solution {
public:
    string clearStars(string s) {
        int n = s.size();
        vector<int> buckets[26];
        vector<bool> removed(n, false);

        for (int i = 0; i < n; i++) {
            if (s[i] == '*') {
                for (int c = 0; c < 26; c++) {
                    if (!buckets[c].empty()) {
                        int idx = buckets[c].back();
                        buckets[c].pop_back();
                        removed[idx] = true;
                        break;
                    }
                }
            } else {
                buckets[s[i] - 'a'].push_back(i);
            }
        }

        string result;
        for (int i = 0; i < n; i++) {
            if (s[i] != '*' && !removed[i]) {
                result += s[i];
            }
        }
        return result;
    }
};
